    edges = []
    lines = input_data.split('\n')[2:]
    for line in lines:
        if not line.strip():
            continue
        a, b = map(int, line.split())
        edges.append((a, b))

    adj = [[] for _ in range(n + 1)]
    for a, b in edges:
        adj[a].append(b)
        adj[b].append(a)

    dist = [0] * (n + 1)

    def dfs_dist(u: int, p: int = -1) -> None:
        for v in adj[u]:
            if v != p:
                dist[v] = dist[u] + 1
                dfs_dist(v, u)

    dfs_dist(1, 1)

    total = sum(dist[1:])
    return f"{total}\n" + " ".join(map(str, range(n)))

