def solution(data):
    import sys
    sys.setrecursionlimit(10000)
    from itertools import combinations

    lines = data.strip().split('\n')
    n = int(lines[0])
    points = []
    for i in range(1, n + 1):
        x, y = map(int, lines[i].strip().split())
        points.append((x, y))

    def cross(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    def on_segment(o, a, b):
        if min(o[0], a[0]) <= b[0] <= max(o[0], a[0]) and min(o[1], a[1]) <= b[1] <= max(o[1], a[1]):
            cross_o_ab = cross(o, a, b)
            return cross_o_ab == 0
        return False

    def same_side(a, b, o, p):
        return cross(o, a, p) * cross(o, b, p) < 0

    total = 0
    for i, j, k in combinations(range(n), 3):
        a, b, c = points[i], points[j], points[k]
        for p1, p2, p3 in combinations(range(n), 3):
            p1, p2, p3 = points[p1], points[p2], points[p3]
            if i == p1 or i == p2 or i == p3 or j == p1 or j == p2 or j == p3 or k == p1 or k == p2 or k == p3:
                continue
            if same_side(a, b, b, c) and same_side(b, c, a, c):
                total += 1
    return f"{total}\n"

