    a = list(map(int, lines[1].split()))

    def f(x):
        while x % k == 0:
            x //= k
        return x

    from functools import lru_cache

    @lru_cache(maxsize=None)
    def solve(state_tuple):
        state = list(state_tuple)
        if len(state) == 1:
            return state[0] == 1

        for i in range(len(state)):
            for j in range(i + 1, len(state)):
