                s = f(s)
                new_state = list(state)
                new_state[i] = s
                result = solve(tuple(new_state))
                if result == 1:
                    x, y = state[i], state[j]
                    idx, bot = i, j
                    return (idx, bot)
        return None

    op = solve(tuple(a))
    if op is None:
