def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def factorize(n):
    factors = []
    d = 2
    while d * d <= n:
        while n % d == 0:
            factors.append(d)
            n //= d
        d += 1
    if n > 1:
        factors.append(n)
    return factors

def minimal_roots_f(n):
    if n == 1:
        return 1
    primes = []
    f = {n: factorize(n)}
    parsed = False
    for ai_str in re.split(r'\s+', n):
        if not parsed and ai_str != '':
            ai = int(ai_str)
            primes.extend(factorize(ai))
            f[ai] = factorize(ai)
            parsed = True
    counter = Counter(primes)
    roots = {}
    for ai in f:
        sub = factorize(f[ai])
        roots[ai] = len(set(sub))
    m = min(roots.values()) if roots else 1
    return max(m + 1, 7)

