def solution(input_data):
    lines = input_data.strip().split('\n')
    if not lines:
        return '0\n'

    n, k = map(int, lines[0].split())
    p = list(map(int, lines[1].split())) if len(lines) > 1 else []

    # Edge case: empty or insufficient input
    if k != len(lines) - 1:
        return '0\n'

    pairs = []
    for i in range(1, k + 1):
        line = lines[i].strip()
        if line:
            x, y = map(int, line.split())
            pairs.append((x, y))

    # Build prerequisite adjacency list
    adj = [[] for _ in range(n + 1)]
    indegree = [0] * (n + 1)

    for i in range(1, n + 1):
        prerequisite = p[i - 1]
        if prerequisite > 0:
            adj[prerequisite].append(i)
            indegree[i] += 1

    # Build special pair graph
    special_adj = [[] for _ in range(n + 1)]
    for x, y in pairs:
        if x == y:
            return '0\n'
        special_adj[x].append(y)

    # Check for cycle in special pairs using visited + rec_stack
    visited = [False] * (n + 1)
    rec_stack = [False] * (n + 1)
    def has_cycle(u):
        visited[u] = True
        rec_stack[u] = True
        for v in special_adj[u]:
            if not visited[v]:
                if has_cycle(v):
                    return True
            elif rec_stack[v]:
                return True
        rec_stack[u] = False
        return False

    for i in range(1, n + 1):
        if special_adj[i] and not visited[i]:
            if has_cycle(i):
                return '0\n'

    # Topological sort (Kahn's algorithm)
    from collections import deque
    q = deque()
    for i in range(1, n + 1):
        if indegree[i] == 0:
            q.append(i)

    result = []
    while q:
        u = q.popleft()
        result.append(u)

        # Process special pairs
        for v in special_adj[u]:
            indegree[v] -= 1
            if indegree[v] == 0:
                q.append(v)

        # Process prerequisites
        for v in adj[u]:
            indegree[v] -= 1
            if indegree[v] == 0:
                q.append(v)

    if len(result) < n:
        return '0\n'

    return ' '.join(map(str, result)) + '\n'

