def can_reach(adj, s, t, removed_set):
    if s == t: return True
    visited = {s}
    queue = [s]
    while queue:
        node = queue.pop(0)
        for neighbor, _ in adj.get(node, []):
            if neighbor not in visited and neighbor not in removed_set:
                visited.add(neighbor)
                queue.append(neighbor)
    return t in visited

