        parent = {v: p for p, v in parent.items()}
        depth = {v: d for d, v in depth.items()}
        order = [1] + [i for i in range(1, num_nodes + 1) if i != 1]

    num_level = depth.values()
    max_depth = max(num_level)

    if max_depth != n - 1:
        return "0\n"

    level_counts = defaultdict(int)
    for i in range(1, num_nodes + 1):
        level_counts[depth[i]] += 1

    expected = {0: 1}
    for i in range(1, n):
        expected[i] = 1 << i

    for d in range(n):
        if level_counts[d] != expected[d]:
            return "0\n"

    candidates = []
    for v in range(1, num_nodes):
        if depth[v] < n - 1:
            children_of_v = [child for child in adj[v] if parent.get(child) == v]

