                for child in children_of_v:
                    for v1 in adj[child]:
                        if v1 != v:
                            siblings_map[id(child)].add(v1)

                candidates.append(v)

    valid = []
    for v in range(1, num_nodes):
        if depth[v] < n - 1:
            children_of_v = [child for child in adj[v] if parent.get(child) == v]
            if children_of_v:
