    def complement(s):
        return ''.join('1' if c == '0' else '0' for c in s)

    def get_canonical(s):
        s_rev = s[::-1]
        c = complement(s)
        c_rev = c[::-1]
        return min(s_rev, s, c, c_rev)

    canonical_set = set()
    for i in range(1 << n):
        s = bin(i)[2:].zfill(n)
        canonical_set.add(get_canonical(s))

    canonical_list = sorted(canonical_set)

    if k < 1 or k > len(canonical_list):
        return '-1\n'

    return canonical_list[k-1] + '\n'

