    lines = input_data.strip().split('\n')
    n, a, b = map(int, lines[0].split())
    p = list(map(int, lines[1].split()))

    num_map = {x: i for i, x in enumerate(p)}

    parent = list(range(n))

    def find(i):
        path = []
        while parent[i] != i:
            path.append(i)
            i = parent[i]
        for node in path:
            parent[node] = i
        return i

    def union(i, j):
        root_i = find(i)
        root_j = find(j)
        if root_i != root_j:
            parent[root_i] = root_j

    for x in p:
        a_comp = a - x
        if a_comp in num_map:
            union(num_map[x], num_map[a_comp])

    for x in p:
        b_comp = b - x
        if b_comp in num_map:
            union(num_map[x], num_map[b_comp])

    result = []
    for x in p:
        x_idx = num_map[x]
        a_comp = a - x
        b_comp = b - x
        root = find(x_idx)
        valid = True
        if a_comp in num_map and not (find(num_map[a_comp]) == root):
            valid = False
        if b_comp in num_map and not (find(num_map[b_comp]) == root):
            valid = False
        result.append('0' if valid else '1')

    return 'YES\n' + ' '.join(result) + '\n' if valid else 'NO\n'

